class Solution:
    def maxPotholes(self, road: str, budget: int) -> int:
        # Lengths of maximal runs of potholes 'x'
        runs = [len(part) for part in road.split('.') if part]
        runs.sort(reverse=True)

        fixed = 0
        for length in runs:
            if budget >= length + 1:
                # fix the entire run
                fixed += length
                budget -= length + 1
            else:
                # partial fix: pay 1 + (potholes fixed) out of what remains
                if budget >= 2:
                    fixed += budget - 1
                break
        return fixed
